export type WorkflowTemplateManifestActionOutput = {
	/** The stable action ID for client-side plan tracking */
	action_ref?: string;
	/** The target entity type for this action */
	entity_type?: ("EVENT" | "GROUP" | "MAIL_MERGE" | "POSITION" | "PROFILE" | "STEP");
	/** The action type, needed to tell BAPTISM apart from MEMBERSHIP within PROFILE */
	type?: ("ASSIGN" | "MEMBERSHIP" | "BAPTISM" | "REMOVE");
	/** Whether this action is restricted (locked) for the current user */
	locked?: boolean;
};

export type WorkflowTemplateManifestStepOutput = {
	/** The stable step ID for client-side plan tracking */
	step_ref?: string;
	/** The promptable actions in this step */
	actions?: Array<WorkflowTemplateManifestActionOutput>;
};

export type WorkflowTemplatePreviewOutput = {
	/** The template UUID */
	id?: string;
	/** The template name */
	name?: string;
	/** The template description */
	description?: string;
	/** The instructions from the backing workflow */
	instructions?: string;
	/** The template's revision timestamp (sync date) */
	revision?: string | null;
	/** The template's step list with actions in display language */
	steps?: Array<WorkflowTemplateStepOutput>;
	/** The step-shaped manifest describing what the wizard will prompt for */
	manifest?: Array<WorkflowTemplateManifestStepOutput>;
};

export type WorkflowTemplateStepActionOutput = {
	/** The stable action ID for client-side plan tracking */
	action_ref?: string;
	/** The action type */
	type?: ("ASSIGN" | "BAPTISM" | "MEMBERSHIP" | "REMOVE");
	/** The apply mode for this action */
	apply_mode?: ("OPTIONAL" | "REQUIRED" | "SUGGESTED");
	/** The target entity type for this action */
	entity_type?: ("EVENT" | "GROUP" | "MAIL_MERGE" | "POSITION" | "PROFILE" | "STEP");
	/** For STEP-typed actions, the target step ID; null otherwise. Also null when the action targets any step, meaning the choice is left open for the person setting up the workflow. */
	target_step_ref?: string | null;
};

export type WorkflowTemplateStepOutput = {
	/** The stable step ID */
	step_ref?: string;
	/** The step name */
	name?: string;
	/** The step description */
	description?: string;
	/** The step instructions */
	instructions?: string;
	/** Days after step creation when it's due */
	due_date_days_later?: number;
	/** The type of due date */
	due_date_type?: ("A" | "MT" | "MD" | "Q" | "R" | "W");
	/** The weekday for weekly due dates */
	due_date_weekday?: string;
	/** The week number for weekly due dates */
	due_date_week_number?: string;
	/** Days before due date to notify managers */
	notify_managers_days?: number;
	/** Whether to notify managers when individuals are assigned */
	pref_notify_managers_assigned?: boolean;
	/** Whether to notify managers when individuals are unassigned */
	pref_notify_managers_unassigned?: boolean;
	/** The actions in this step (all types, including non-promptable) */
	actions?: Array<WorkflowTemplateStepActionOutput>;
};

export type WorkflowTemplateSummaryOutput = {
	/** The template UUID */
	id?: string;
	/** The template name */
	name?: string;
	/** The template description */
	description?: string;
	/** The number of steps in the template */
	step_count?: number;
	/** The number of targets (prompts) the wizard will ask for */
	target_count?: number;
	/** Whether the template is Pushpay-provided (system-defined) */
	is_system_defined?: boolean;
	/** When the template was last used to create a workflow, or null if never used */
	last_used_date?: string | null;
	/** When the template was last modified */
	date_modified?: string | null;
};
